{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Parks and roads on one map.",
  "mark": {
    "type": "geoshape",
    "strokeWidth": 3,
    "fillOpacity": 0.4
  },
  "encoding": {
    "color": {
      "field": "layer",
      "type": "nominal",
      "title": "Layer"
    },
    "stroke": {
      "field": "layer",
      "type": "nominal",
      "legend": null
    },
    "tooltip": [
      {
        "field": "name",
        "type": "nominal"
      }
    ]
  }
}
